#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.07944230000000001, 0.17440075500000002, -0.004469174999999999], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.038344960000000004, 'zmax': 0.03834496, 'profiles': [{'outer': [[-0.124515815, -0.028335195000000007], [-0.124515815, 0.025949994999999976], [-0.124361215, 0.028931494999999974], [-0.12319070500000001, 0.03149335499999997], [-0.120297555, 0.03568952499999997], [-0.11663142500000001, 0.03984152499999999], [-0.11300948499999999, 0.04191752499999998], [-0.11188314499999999, 0.04222672499999999], [-0.10728943499999999, 0.043065944999999994], [-0.09317705500000001, 0.044876924999999984], [-0.07656906499999999, 0.04684250499999998], [-0.06773501500000001, 0.047725904999999985], [-0.058923055, 0.048476804999999984], [-0.050596965, 0.04907309499999998], [-0.038074715, 0.04971357499999998], [-0.025353695, 0.049956504999999984], [0.025331615000000002, 0.049956504999999984], [0.038074715, 0.04971357499999998], [0.043485565000000004, 0.04947062499999999], [0.050596975, 0.04907309499999998], [0.058923054999999995, 0.048476804999999984], [0.06773501500000001, 0.047725904999999985], [0.076569045, 0.04684250499999998], [0.09317705500000001, 0.044876924999999984], [0.107289425, 0.043065944999999994], [0.111883125, 0.04222672499999999], [0.113009475, 0.04191752499999998], [0.11663142500000001, 0.03984152499999999], [0.120297555, 0.03568952499999997], [0.123190715, 0.03149335499999997], [0.124339125, 0.028931494999999974], [0.124515815, 0.025949994999999976], [0.124515815, -0.028335195000000007], [0.12431704500000001, -0.032067575000000015], [0.123014025, -0.03566744500000002], [0.119833775, -0.041034125000000005], [0.11601303500000001, -0.046157875000000015], [0.112545685, -0.04871974500000001], [0.10711274500000001, -0.049713565000000015], [0.10084057499999999, -0.04995650500000001], [0.09317705500000001, -0.049912345000000025], [0.08504972499999999, -0.04958105500000001], [0.076569045, -0.04902892500000003], [0.06775709499999999, -0.04827804500000002], [0.058779023153821164, -0.04721318460781557], [0.052032495, -0.04662165500000001], [0.043993525, -0.045406975000000016], [0.037125055000000004, -0.04390517500000002], [0.031912975, -0.042447575000000015], [0.031117905, -0.04209420500000002], [0.027142585000000004, -0.03988569500000003], [0.023851915, -0.03635207500000001], [0.018949015, -0.029086075000000017], [0.018287067687353793, -0.02842675092076512], [0.017358885, -0.028313105000000005], [0.004461185000000001, -0.027495955000000016], [5.000000000837668e-09, -0.02731927500000003], [-0.004483274999999999, -0.027495955000000016], [-0.017358884999999998, -0.028313105000000005], [-0.018287076398228533, -0.02842675093715028], [-0.018949015, -0.029086075000000017], [-0.023851914999999998, -0.03635207500000001], [-0.027142595, -0.03988569500000003], [-0.031117915, -0.04209420500000002], [-0.031935065, -0.042447575000000015], [-0.037147145, -0.04390517500000002], [-0.044015615, -0.045406975000000016], [-0.052032505, -0.04662165500000001], [-0.05870432399082172, -0.047205073081509], [-0.06775710500000001, -0.04827804500000002], [-0.076591135, -0.04902892500000003], [-0.08507182499999999, -0.04958105500000001], [-0.09319914500000001, -0.049912345000000025], [-0.10084057499999999, -0.04995650500000001], [-0.10713483500000001, -0.049713565000000015], [-0.108172835, -0.04955897500000002], [-0.112545685, -0.04871974500000001], [-0.116013055, -0.046157875000000015], [-0.11985584499999999, -0.041034125000000005], [-0.123014035, -0.03566744500000002], [-0.12431704499999999, -0.032067575000000015]], 'holes': []}], 'simplify_tolerance': 4.9806326e-05, 'sketch_entity_count': 81}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
